#!/usr/bin/env python3
"""Local emulation of check.py (same child runs, same audits, no seccomp)."""
import json, os, subprocess, sys, time, resource
from pathlib import Path
sys.path.insert(0, '/workspace')
from audit import audit

WALL = 120
def unique(pairs):
    out={}
    for k,v in pairs:
        if k in out: raise ValueError("dup")
        out[k]=v
    return out
def rej(x): raise ValueError("nonfinite")
def decode(data): return json.loads(data.decode(), object_pairs_hook=unique, parse_constant=rej)

def run(entry, data, argv=None, raw=False):
    t0=time.monotonic()
    env=dict(os.environ, PYTHONUNBUFFERED="1", PYTHONDONTWRITEBYTECODE="1",
             PYTHONHASHSEED="0", TMPDIR="/workspace/tmp")
    p=subprocess.Popen(argv or [sys.executable,"-B",str(entry)], stdin=subprocess.PIPE,
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
    out,err=p.communicate(data, timeout=WALL)
    if p.returncode: raise ValueError("child exited %d: %s"%(p.returncode, err.decode()[:400]))
    if err: print("   stderr:", err.decode()[:300])
    return out if raw else decode(out)

def main():
    entry=Path(sys.argv[1] if len(sys.argv)>1 else '/workspace/submission/main.py')
    examples=Path('/workspace/examples')
    fixtures=sorted(examples.glob("*.in.json"))
    for fx in fixtures:
        exp=decode(fx.with_name(fx.name.replace(".in.",".out.")).read_bytes())
        payload=fx.read_bytes()
        actual=run(entry,payload)
        try: req=decode(payload)
        except ValueError: req=None
        audit(req,actual,exp)
        print("PASS json", fx.name)
    binary=Path('/workspace/tmp')/('harness-engine-%d'%os.getpid())
    run(entry, b'', argv=['g++','-O2','-std=c++17',str(entry.parent/'engine.cpp'),'-o',str(binary)], raw=True)
    for fx in sorted(examples.glob('*.in.native')):
        exp=fx.with_name(fx.name.replace('.in.','.out.')).read_bytes()
        actual=run(entry, fx.read_bytes(), argv=[str(binary)], raw=True)
        if actual.split()!=exp.split(): raise ValueError("native stage output "+fx.name)
        print("PASS native", fx.name)
    print("ALL PASS")
main()
EOF
